<script setup>import { onMounted, ref } from "vue"; import UserLayout from "../../layouts/UserLayout.vue"; import StatusBadge from "../../components/StatusBadge.vue"; import { requestService } from "../../services/api"; const items = ref([]), loading = ref(true), error = ref(""); const load = async () => { try { items.value = (await requestService.mine()).data; } catch (exception) { error.value = exception.message; } finally { loading.value = false; } }; const date = (value) => value ? new Date(value).toLocaleDateString("fr-FR") : "—"; onMounted(load);</script><template><UserLayout><section class="mx-auto max-w-7xl px-5 py-12"><h1 class="text-3xl font-bold">Mes demandes</h1><p class="mt-2 text-slate-500">Suivez l'avancement de vos emprunts.</p><div v-if="loading" class="py-16 text-center"><span class="loading loading-spinner text-[#17482d]"></span></div><div v-else-if="error" class="alert alert-error mt-7">{{ error }}</div><div v-else-if="!items.length" class="mt-7 rounded-2xl border border-dashed p-12 text-center text-slate-500">Vous n'avez aucune demande.</div><div v-else class="mt-7 overflow-x-auto rounded-2xl border border-slate-100 bg-white"><table class="table"><thead><tr><th>Matériel</th><th>Quantité</th><th>Type</th><th>Début</th><th>Retour prévu</th><th>Statut</th><th>Créée le</th></tr></thead><tbody><tr v-for="item in items" :key="item.id"><td>#{{ item.materiel_id }}</td><td>{{ item.quantite }}</td><td class="capitalize">{{ item.type_emprunt }}</td><td>{{ date(item.date_debut) }}</td><td>{{ date(item.date_fin_prevue) }}</td><td><StatusBadge :status="item.statut" /><p v-if="item.motif_refus" class="mt-1 max-w-40 text-xs text-error">{{ item.motif_refus }}</p></td><td>{{ date(item.date_creation) }}</td></tr></tbody></table></div></section></UserLayout></template>
